// Eight-bit direct QIF phase-transition lookup, generated by tools/generate_rom.py
// Signed weight encoding: two's-complement Q4.4, physical weight = weight / 16.
// Phase: 8-bit circular phase; one free-running period = 256 integer time ticks.
// Combinational memory read is a baseline, not optimized FPGA BRAM.
module qif_h8_rom #(
    parameter ROM_FILE = "qif8_prototype/rtl/qif_h8.mem"
) (
    input  logic [7:0] phase_in,
    input  logic signed [7:0] weight_in,
    output logic [7:0] phase_out
);
    logic [7:0] rom [0:65535];
    logic [15:0] rom_addr;
    assign rom_addr = {weight_in[7:0], phase_in};
    initial $readmemh(ROM_FILE, rom);
    assign phase_out = rom[rom_addr];
endmodule
